import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.evaluation.NativeProjectedBindingSet;
import org.eclipse.rdf4j.sail.lmdb.model.LmdbValue;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class LmdbPositionRoutingIntegrationTest {

	@Test
	void repeatedSubjectAndObjectRoutesThroughNativeMaterializer(@TempDir File directory) throws Exception {
		assertRouting(directory, "SELECT ?a WHERE { ?a a ?a }", "a", true, false);
	}

	@Test
	void subqueryAliasesAndComputedValuesPreserveLexicalRoles(@TempDir File directory) throws Exception {
		assertRouting(directory, "SELECT ?alias ?text WHERE { { SELECT ?a WHERE { ?a a ?a } } "
				+ "BIND(?a AS ?alias) BIND(STR(?alias) AS ?text) }", "alias", false, true);
	}

	private static void assertRouting(File directory, String query, String binding, boolean nativeProjection,
			boolean computedText) throws Exception {
		LmdbStore store = new LmdbStore(directory, new LmdbStoreConfig("spoc,posc,ospc")
				.setNativeEvaluationEnabled(true)
				.setValueCacheSize(64));
		SailRepository repository = new SailRepository(store);
		IRI expected = SimpleValueFactory.getInstance().createIRI("urn:position-routing:self");
		try (var connection = repository.getConnection()) {
			connection.add(expected, RDF.TYPE, expected);
			ValueStore values = store.getBackingStore().valueStore();
			long id = values.getId(expected, false);
			assertFalse(ValueIds.isInlined(id));
			TupleQuery prepared = connection.prepareTupleQuery(query);
			readSingle(prepared); // Exercise query initialization before observing cache admissions.
			values.clearCaches();
			for (int mask : new int[] { 0, 1, 2, 4, 8 }) {
				assertNull(values.cachedValue(id, mask));
			}

			BindingSet row = readSingle(prepared);
			if (nativeProjection) {
				assertInstanceOf(NativeProjectedBindingSet.class, row);
			}
			assertEquals(expected, row.getValue(binding));
			LmdbValue value = assertInstanceOf(LmdbValue.class, row.getValue(binding));
			assertTrue(value.isInitialized(), "the Sail result boundary must initialize dictionary values");
			assertEquals(id, value.getInternalID());
			if (computedText) {
				assertEquals(expected.stringValue(), row.getValue("text").stringValue());
			}
			assertNotNull(values.cachedValue(id, ValuePosition.SUBJECT));
			for (int mask : new int[] { 0, 2, 4, 8 }) {
				assertNull(values.cachedValue(id, mask), "combined subject/object uses must select only subject");
			}
		} finally {
			repository.shutDown();
		}
	}

	private static BindingSet readSingle(TupleQuery query) {
		try (var rows = query.evaluate()) {
			assertTrue(rows.hasNext());
			BindingSet row = rows.next();
			assertFalse(rows.hasNext());
			return row;
		}
	}
}
